setup.sql:
GRANT EXECUTE ON shop.* TO 'app'@'%';
DROP TABLE IF EXISTS shop.deadlock_log;
CREATE TABLE shop.deadlock_log (id INT AUTO_INCREMENT PRIMARY KEY, at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
DROP PROCEDURE IF EXISTS shop.deadlock_worker;
DELIMITER //
CREATE PROCEDURE shop.deadlock_worker(a BIGINT, b BIGINT, n INT) SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    INSERT INTO shop.deadlock_log () VALUES ();
  END;
  WHILE i < n DO
    START TRANSACTION;
    UPDATE shop.orders SET amount = amount + 1 WHERE id = a;
    DO SLEEP(0.05);
    UPDATE shop.orders SET amount = amount + 1 WHERE id = b;
    COMMIT;
    SET i = i + 1;
  END WHILE;
END//
DELIMITER ;
